css:
.racine-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #243029;
    background: linear-gradient(165deg, #f3f7ef 0%, #eef4ea 55%, #e7f0e6 100%);
    border-radius: 18px;
}

.racine-container * {
    box-sizing: border-box;
}

.racine-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1d3b2a 0%, #2f6e44 55%, #4f9d5f 100%);
    color: #f1f8ef;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(29, 59, 42, 0.30);
}

.racine-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.racine-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffe2a6;
    background: rgba(255, 226, 166, 0.14);
    border: 1px solid rgba(255, 226, 166, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.racine-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6ecd4;
}

.racine-paths {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.racine-path {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(36, 48, 41, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.racine-path-vc { border-left: 5px solid #b8542b; }
.racine-path-rbf { border-left: 5px solid #2f6e44; }
.racine-path-partner { border-left: 5px solid #c79313; }

.racine-path-name {
    font-weight: 800;
    font-size: 1.02rem;
    color: #1d3b2a;
}

.racine-path-vc .racine-path-name { color: #a8461f; }
.racine-path-rbf .racine-path-name { color: #2f6e44; }
.racine-path-partner .racine-path-name { color: #a87b0a; }

.racine-path-meta {
    font-size: 0.81rem;
    color: #5b6a5e;
    line-height: 1.4;
}

.racine-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #46594c;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.racine-period-counter #currentDay,
.racine-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f6e44;
}

.racine-round-name {
    background: rgba(47, 110, 68, 0.14);
    color: #235033;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.racine-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8461f;
    background: rgba(184, 84, 43, 0.12);
    border: 1px solid rgba(184, 84, 43, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.racine-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.racine-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(36, 48, 41, 0.08);
    border-top: 4px solid #2f6e44;
}

.racine-card-runway { border-top-color: #b8542b; }
.racine-card-arr { border-top-color: #2f6e44; }
.racine-card-identity { border-top-color: #4f9d5f; }
.racine-card-network { border-top-color: #c79313; }

.racine-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c7d70;
}

.racine-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1d3b2a;
    font-variant-numeric: tabular-nums;
}

.racine-card-runway .racine-value { color: #b8542b; }
.racine-card-arr .racine-value { color: #2f6e44; }
.racine-card-identity .racine-value { color: #4f9d5f; }
.racine-card-network .racine-value { color: #a87b0a; }

/* The runway clock is the loudest sound in the room — make it the dominant KPI. */
.racine-card-runway .racine-value { font-size: 2.9rem; }

.racine-card-runway.racine-runway-danger { border-top-color: #c0392b; }
.racine-card-runway.racine-runway-danger .racine-value { color: #c0392b; }
.racine-card-runway.racine-runway-safe { border-top-color: #2f6e44; }
.racine-card-runway.racine-runway-safe .racine-value { color: #2f6e44; }

.racine-card-identity.racine-identity-danger { border-top-color: #c0392b; }
.racine-card-identity.racine-identity-danger .racine-value { color: #c0392b; }

.racine-sublabel {
    font-size: 0.76rem;
    color: #7a8a7e;
    line-height: 1.35;
}

.racine-growth-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dde6dc;
    color: #46594c;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.racine-growth-bar #growthDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #a8461f;
    font-weight: 800;
}

.racine-growth-bar.racine-growth-good #growthDisplay { color: #2f6e44; }
.racine-growth-bar.racine-growth-warn #growthDisplay { color: #c79313; }

.racine-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f6e44;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(36, 48, 41, 0.07);
}

.racine-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.racine-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1d3b2a;
    margin-bottom: 6px;
}

.racine-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3c4d40;
}

.racine-briefing-text strong { color: #2f6e44; }
.racine-briefing-text em { color: #a8461f; font-style: italic; }

.racine-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(36, 48, 41, 0.07);
}

.racine-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1d3b2a;
    border-bottom: 2px solid #e6ede4;
    padding-bottom: 8px;
}

.racine-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c3d31;
    margin: 14px 0 6px;
}

.racine-container select,
.racine-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6d3c4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #243029;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.racine-container select:focus,
.racine-container input[type="number"]:focus {
    outline: none;
    border-color: #2f6e44;
    box-shadow: 0 0 0 3px rgba(47, 110, 68, 0.16);
}

.racine-container select option {
    background-color: #ffffff;
    color: #243029;
}

.racine-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f6e44;
}

.racine-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #46594c;
    margin-top: 4px;
}

.racine-range-readout span:nth-child(2) {
    color: #2f6e44;
    font-weight: 800;
}

.racine-hint {
    font-size: 0.8rem;
    color: #7a8a7e;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.racine-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.racine-container .btn-primary {
    background: linear-gradient(135deg, #2f6e44 0%, #4f9d5f 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(47, 110, 68, 0.32);
}

.racine-container .btn-primary:hover {
    filter: brightness(1.07);
}

.racine-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c6d3c4;
    color: #5b6a5e;
    background: transparent;
}

.racine-coach {
    background: linear-gradient(160deg, #1d3b2a 0%, #224832 100%);
    color: #e3f1e1;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(29, 59, 42, 0.24);
}

.racine-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffe2a6;
    margin-bottom: 8px;
}

.racine-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.racine-coach-body strong { color: #8fe3a0; }
.racine-coach-body em { color: #ffe2a6; font-style: italic; }

.racine-history,
.racine-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(36, 48, 41, 0.07);
}

.racine-history h3,
.racine-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1d3b2a;
}

.racine-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3c4d40;
}

.racine-container table#usfHistoryTable th {
    background: #eef4ea;
    color: #2f6e44;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e3d2;
}

.racine-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1ed;
    color: #3c4d40;
}

.racine-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6faf4;
}

.racine-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .racine-container {
        padding: 14px;
    }
    .racine-header h1 {
        font-size: 1.7rem;
    }
    .racine-paths {
        flex-direction: column;
    }
    .racine-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .racine-value {
        font-size: 2rem;
    }
    .racine-card-runway .racine-value {
        font-size: 2.2rem;
    }
    .racine-clock {
        margin-left: 0;
    }
    .racine-period-counter {
        font-size: 0.88rem;
    }
    .racine-growth-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .racine-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (gop- prefix; mission-green theme) ---- */
.gop-completion { padding: 8px 4px 4px; }
.gop-cm-head { text-align: center; margin-bottom: 16px; }
.gop-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f8f5b; }
.gop-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #7a8a7e; }
.gop-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #16321f; }
.gop-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.gop-cm-yes { background: rgba(47,143,91,0.14); color: #2f8f5b; border: 1px solid rgba(47,143,91,0.45); }
.gop-cm-mid { background: rgba(120,138,126,0.14); color: #5f7266; border: 1px solid rgba(120,138,126,0.42); }
.gop-cm-no  { background: rgba(200,64,52,0.12); color: #c84034; border: 1px solid rgba(200,64,52,0.42); }
.gop-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.gop-cm-metric { flex: 1 1 100px; min-width: 92px; background: rgba(47,143,91,0.07); border: 1px solid rgba(47,143,91,0.20); border-radius: 10px; padding: 10px 8px; text-align: center; }
.gop-cm-mv { display: block; font-size: 1.15rem; font-weight: 800; color: #2f8f5b; }
.gop-cm-ml { display: block; font-size: 0.66rem; margin-top: 4px; color: #7a8a7e; text-transform: uppercase; letter-spacing: 0.03em; }
.gop-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #16321f; }
.gop-cm-insights { margin: 0; padding-left: 20px; }
.gop-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #3a4a40; }

