(function() {
    'use strict';

    class GrowingOnPurposeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Growing on Purpose`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Racine SAS) ----
            this.START_ARR = 1.4;          // €1.4M ARR (stalled)
            this.START_CASH = 855;         // €855K cash on hand
            this.BASE_BURN = 95;           // €95K net monthly burn
            this.START_RUNWAY = 9.0;       // ~9 months
            this.START_IDENTITY = 82;      // identity-alignment score (decision tree: drops to 41 on the VC trap)
            this.MILESTONE_ARR = 3.0;      // €3M ARR credible next-raise threshold
            this.NETWORK_MAX = 600;        // €600K resourcefulness ceiling
            this.NETWORK_FLOOR = 400;      // €400K low end of the network value band
            this.SALES_HIRE = 180;         // €180K/yr enterprise sales hire
            this.COMPETITOR_RAISE = 12;    // €12M competitor Series A
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    arr: this.START_ARR,                 // €M annual recurring revenue
                    cash: this.START_CASH,               // €K cash on hand
                    burn: this.BASE_BURN,                // €K net monthly burn
                    runway: this.START_RUNWAY,           // months
                    identity: this.START_IDENTITY,       // identity-alignment score 0–100
                    network: 0,                          // €K resourcefulness value unlocked
                    growth: 0,                           // annualised growth rate (%) implied by the plan
                    capitalRaised: 0,                    // €M new capital secured
                    pathChosen: ``,                      // vc | rbf | partner

                    // ---- Sticky, run-defining penalty flags (set when an error is committed;
                    // they GATE the top verdict and CAP KPIs — a later good round cannot wash them out). ----
                    valuationTunnelRun: false,           // took VC AND accepted the any-customer clause + 2x pref
                    bootstrapBlindRun: false,            // bootstrapped while ignoring the competitor war chest
                    freeMoneyRun: false,                 // partnership without pricing exclusivity / the board seat
                    networkNeglectRun: false,            // skipped network activation, left €400–600K on the table
                    salesDelayRun: false,                // delayed / skipped the €180K hire that every path assumes
                    channelBlocked: false,               // exclusivity blocked the 30%-of-pipeline retail channel
                    misdiagnosedRun: false,              // misread the stall / runway / identity in Round 1
                    hyperGrowthRun: false,               // chased a velocity the venture's resources can't sustain (not "on purpose")

                    arrHistory: [this.START_ARR],
                    runwayHistory: [this.START_RUNWAY],
                    identityHistory: [this.START_IDENTITY],
                    networkHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the concept's COMMON ERRORS so a blind
                // click-through CANNOT auto-win: misdiagnosis, network neglect, the VC
                // valuation trap with accepted clauses, a delayed hire and hyper-growth.
                state.decisions = {
                    cause: `product`,
                    runwayRead: `plenty`,
                    identityKeep: `growth`,
                    focus: 50,
                    pilots: `skip`,
                    comarketing: `no`,
                    attention: 20,
                    path: `vc`,
                    terms: `accept`,
                    shock: `cave`,
                    hire: `delay`,
                    milestone: `hyper`,
                    pitch: `valuation`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ca = document.getElementById(`causeInput`);
                const rr = document.getElementById(`runwayReadInput`);
                const ik = document.getElementById(`identityKeepInput`);
                const fo = document.getElementById(`focusInput`);
                if (ca) decisions.cause = ca.value;
                if (rr) decisions.runwayRead = rr.value;
                if (ik) decisions.identityKeep = ik.value;
                if (fo) decisions.focus = parseInt(fo.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const pi = document.getElementById(`pilotsInput`);
                const co = document.getElementById(`comarketingInput`);
                const at = document.getElementById(`attentionInput`);
                if (pi) decisions.pilots = pi.value;
                if (co) decisions.comarketing = co.value;
                if (at) decisions.attention = parseInt(at.value, 10);
                if (!Number.isFinite(decisions.attention) || decisions.attention < 0 || decisions.attention > 100) {
                    warn(`warn_attention_range`); return false;
                }
            } else if (round === 3) {
                const pa = document.getElementById(`pathInput`);
                const te = document.getElementById(`termsInput`);
                const sh = document.getElementById(`shockInput`);
                if (pa) decisions.path = pa.value;
                if (te) decisions.terms = te.value;
                if (sh) decisions.shock = sh.value;
                if (!decisions.path) { warn(`warn_path_required`); return false; }
            } else if (round === 4) {
                const hi = document.getElementById(`hireInput`);
                const mi = document.getElementById(`milestoneInput`);
                const pt = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (hi) decisions.hire = hi.value;
                if (mi) decisions.milestone = mi.value;
                if (pt) decisions.pitch = pt.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let arrDelta = 0, identityDelta = 0, networkDelta = 0, growthDelta = 0;
            let burnDelta = 0, cashDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Diagnose: stall, runway, identity (Common Error: misdiagnosis). ----
                switch (d.cause) {
                    case `undersold`: identityDelta += 1; growthDelta += 1; coachKey = `coach_r1_undersold`; break;
                    case `product`: ds.misdiagnosedRun = true; growthDelta -= 1; coachKey = `coach_r1_product`; break;
                    case `mission`: ds.misdiagnosedRun = true; identityDelta -= 3; coachKey = `coach_r1_mission`; break;
                    case `luck`: ds.misdiagnosedRun = true; growthDelta -= 2; coachKey = `coach_r1_luck`; break;
                }

                switch (d.runwayRead) {
                    case `nine`: identityDelta += 1; break;
                    case `plenty`: ds.misdiagnosedRun = true; if (coachKey === `coach_default`) coachKey = `coach_r1_plenty`; break;
                    case `ignore`: ds.misdiagnosedRun = true; coachKey = `coach_r1_ignore`; break;
                }

                switch (d.identityKeep) {
                    case `mission`: identityDelta += 4; coachKey = (d.cause === `undersold` && d.runwayRead === `nine`) ? `coach_r1_sharp` : `coach_r1_identity`; break;
                    case `growth`: ds.misdiagnosedRun = true; identityDelta -= 4; coachKey = `coach_r1_growthkeep`; break;
                    case `none`: ds.misdiagnosedRun = true; identityDelta -= 6; coachKey = `coach_r1_nonekeep`; break;
                }

                // Founder attention on the decision: too little = drift, too much now = neglect later.
                if (d.focus >= 40 && d.focus <= 70) { growthDelta += 1; }
                else if (d.focus < 20) { growthDelta -= 1; }

                summaryKey = (d.cause === `undersold` && d.runwayRead === `nine` && d.identityKeep === `mission`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ---- Activate the network for resourcefulness (Common Error: network neglect / over-activation). ----
                let unlocked = 0;
                let pilotMoves = 0;

                switch (d.pilots) {
                    case `all`: unlocked += 300; pilotMoves = 3; identityDelta += 3; break;   // three warm enterprise pilots
                    case `some`: unlocked += 110; pilotMoves = 1; identityDelta += 1; break;
                    case `skip`: ds.networkNeglectRun = true; coachKey = `coach_r2_skip`; break;
                }

                switch (d.comarketing) {
                    case `both`: unlocked += 250; identityDelta += 2; break;                  // co-marketing + shared engineer
                    case `comarketing`: unlocked += 130; identityDelta += 1; break;
                    case `no`: if (d.pilots === `skip`) ds.networkNeglectRun = true; break;
                }

                // Attention budget: network value is real but trades against fund-raising time.
                const net = d.attention / 100;
                // Scale unlocked value by how much founder attention actually backs it.
                unlocked = Math.round(unlocked * (0.5 + 0.5 * Math.min(1, net / 0.5)));

                if (d.attention >= 25 && d.attention <= 55) {
                    // Balanced split — network leveraged AND fund-raising protected.
                    networkDelta += unlocked;
                    if (pilotMoves >= 3 || d.comarketing === `both`) coachKey = `coach_r2_balanced`;
                } else if (d.attention < 25) {
                    // Under-activation: most of the value left on the table.
                    networkDelta += Math.round(unlocked * 0.55);
                    if (unlocked < 200) { ds.networkNeglectRun = true; if (coachKey === `coach_default`) coachKey = `coach_r2_under`; }
                } else {
                    // Over-activation: lovely momentum, but the funding process is starved (decision tree #5).
                    networkDelta += unlocked;
                    burnDelta += 6;                                  // extra months of founder time = real cost
                    growthDelta -= 1;
                    coachKey = `coach_r2_over`;
                }

                ds.network = Math.min(this.NETWORK_MAX, ds.network + networkDelta);
                networkDelta = ds.network - (ds.networkHistory.length ? ds.networkHistory[ds.networkHistory.length - 1] : 0);

                summaryKey = (ds.network >= this.NETWORK_FLOOR && d.attention >= 25 && d.attention <= 55) ? `sum_r2_good` :
                             (ds.networkNeglectRun ? `sum_r2_neglect` :
                             (d.attention > 55 ? `sum_r2_over` : `sum_r2_weak`));
            } else if (round === 3) {
                // ---- Choose the growth path & reconcile identity (Common Errors 1, 2, 3 + the shock). ----
                ds.pathChosen = d.path;
                // Network leverage improves the terms available on every path.
                const leverage = ds.network / this.NETWORK_MAX;   // 0..1

                if (d.path === `vc`) {
                    // €6M raise, €24M valuation — capital and growth, but the clauses bite.
                    ds.capitalRaised = 6;
                    cashDelta += 6000 - (cashDelta);                // huge cash injection (€K)
                    growthDelta += 14;
                    arrDelta += 0.35;
                    if (d.terms === `accept` || d.shock === `cave` || d.shock === `panic`) {
                        // VALUATION TUNNEL VISION — the headline anti-pattern.
                        ds.valuationTunnelRun = true;
                        identityDelta -= 41;                        // 82 -> ~41 per the decision tree
                        coachKey = `coach_r3_vctrap`;
                    } else if (d.terms === `renegotiate`) {
                        // Defended mission selectivity, dropped the any-customer clause / softened the pref.
                        identityDelta -= 6 - Math.round(leverage * 4);   // leverage buys back terms
                        coachKey = `coach_r3_vcrenegotiate`;
                    } else { // reject all strings on a VC deal effectively kills it
                        ds.capitalRaised = 0; cashDelta -= 6000; growthDelta -= 8;
                        coachKey = `coach_r3_vcreject`;
                    }
                } else if (d.path === `rbf`) {
                    // Bootstrap + €1.5M revenue-based finance — identity-preserving, slower.
                    ds.capitalRaised = 1.5;
                    cashDelta += 1500;
                    growthDelta += 4 + Math.round(leverage * 6);     // network leverage is how RBF still grows
                    identityDelta += 4;
                    burnDelta += 4;                                  // RBF cash-flow claim raises effective burn
                    coachKey = `coach_r3_rbf`;
                    if (d.terms === `reject` && ds.network < this.NETWORK_FLOOR) {
                        // Identity purism without the network to compensate = under-capitalised vs the €12M rival.
                        ds.bootstrapBlindRun = true;
                        growthDelta -= 6;
                        coachKey = `coach_r3_bootstrapblind`;
                    }
                } else if (d.path === `partner`) {
                    // Strategic partnership — €2M + distribution, exclusivity + board seat.
                    ds.capitalRaised = 2;
                    cashDelta += 2000;
                    growthDelta += 9;
                    arrDelta += 0.15;
                    if (d.terms === `accept` || d.shock === `cave` || d.shock === `panic`) {
                        // FREE-MONEY ILLUSION — exclusivity blocks the 30%-of-pipeline retail channel + board veto.
                        ds.freeMoneyRun = true;
                        ds.channelBlocked = true;
                        identityDelta -= 16;
                        growthDelta -= 10;                           // the blocked channel was 30% of pipeline
                        arrDelta -= 0.2;
                        coachKey = `coach_r3_partnertrap`;
                    } else if (d.terms === `renegotiate`) {
                        // Negotiated exclusivity down and capped the board seat.
                        identityDelta -= 3;
                        coachKey = `coach_r3_partnerrenegotiate`;
                    } else {
                        ds.capitalRaised = 0; cashDelta -= 2000; growthDelta -= 5;
                        coachKey = `coach_r3_partnerreject`;
                    }
                }

                // Holding the line on the shock (and not having caved/panicked) protects identity and the channel.
                if (d.shock === `hold`) {
                    identityDelta += 5;
                    if (ds.network >= this.NETWORK_FLOOR) { growthDelta += 3; }   // network is the fallback if a deal slips
                    if (coachKey === `coach_r3_vcrenegotiate` || coachKey === `coach_r3_partnerrenegotiate` || coachKey === `coach_r3_rbf`) {
                        coachKey = `coach_r3_held`;
                    }
                } else if (d.shock === `panic`) {
                    identityDelta -= 4; growthDelta -= 3;
                }

                summaryKey = (d.terms === `renegotiate` && d.shock === `hold`) ? `sum_r3_reconciled` :
                             (ds.valuationTunnelRun ? `sum_r3_vctrap` :
                             (ds.freeMoneyRun ? `sum_r3_partnertrap` :
                             (ds.bootstrapBlindRun ? `sum_r3_bootstrapblind` : `sum_r3_weak`)));
            } else if (round === 4) {
                // ---- 18-month sustainable-growth plan & board pitch (Common Error: over-conservatism on burn). ----
                switch (d.hire) {
                    case `now`: growthDelta += 8; arrDelta += 0.45; burnDelta += 15; coachKey = `coach_r4_hirenow`; break;   // €180K/yr ≈ €15K/mo
                    case `delay`: ds.salesDelayRun = true; growthDelta -= 6; arrDelta -= 0.1; coachKey = `coach_r4_hiredelay`; break;
                    case `never`: ds.salesDelayRun = true; growthDelta -= 10; arrDelta -= 0.25; coachKey = `coach_r4_hirenever`; break;
                }

                switch (d.milestone) {
                    case `credible`: growthDelta += 5; identityDelta += 4; arrDelta += 0.3; if (d.hire === `now`) coachKey = `coach_r4_credible`; break;
                    case `hyper`: ds.hyperGrowthRun = true; growthDelta += 9; identityDelta -= 10; burnDelta += 12; arrDelta += 0.2; coachKey = `coach_r4_hyper`; break;   // unsustainable rate breaks resources & identity — gates the "on purpose" verdict
                    case `flat`: growthDelta -= 8; arrDelta -= 0.2; coachKey = `coach_r4_flat`; break;
                }

                switch (d.pitch) {
                    case `convergence`: identityDelta += 4; growthDelta += 2; if (d.milestone === `credible` && d.hire === `now`) coachKey = `coach_r4_convergence`; break;
                    case `valuation`: identityDelta -= 3; coachKey = `coach_r4_pitchval`; break;
                    case `harmony`: growthDelta -= 4; coachKey = `coach_r4_pitchharmony`; break;
                }

                if (d.conviction >= 60) { identityDelta += 2; }
                else if (d.conviction <= 25) { growthDelta -= 2; }

                summaryKey = (d.hire === `now` && d.milestone === `credible` && d.pitch === `convergence`) ? `sum_r4_good` :
                             (ds.salesDelayRun ? `sum_r4_delay` :
                             (d.milestone === `hyper` ? `sum_r4_hyper` : `sum_r4_weak`));
            }

            // ---- Apply deltas. Growth feeds ARR over the horizon; cash and burn drive runway. ----
            ds.growth = Math.max(-20, Math.min(120, Math.round(ds.growth + growthDelta)));
            ds.burn = Math.max(40, Math.round(ds.burn + burnDelta));
            ds.cash = Math.max(0, Math.round(ds.cash + cashDelta));

            // ARR moves with the directly-applied delta PLUS a slice of the implied growth rate.
            // A clean, balanced run must be able to reach the €3M next-raise milestone; the sticky
            // caps below still hold the anti-patterns short of it, so the realisation rate can be
            // strong without letting a flawed run cross the line.
            const growthArrGain = Math.max(0, ds.growth) / 100 * 0.60 * ds.arr;   // partial-period realisation
            ds.arr = Math.max(0, Math.round((ds.arr + arrDelta + growthArrGain) * 100) / 100);

            ds.identity = Math.max(0, Math.min(100, Math.round(ds.identity + identityDelta)));

            // Runway = cash ÷ net monthly burn (months). Capital raises extend it; burn shortens it.
            ds.runway = Math.round((ds.cash / ds.burn) * 10) / 10;

            // ---- Sticky caps: the run-defining errors GATE outcomes regardless of later good rounds. ----
            if (ds.valuationTunnelRun) {
                ds.identity = Math.min(ds.identity, 45);     // the moat is gone; later rounds cannot rebuild it past this
            }
            if (ds.bootstrapBlindRun) {
                ds.arr = Math.min(ds.arr, 1.6);              // flat ARR vs the €12M-funded rival
                ds.growth = Math.min(ds.growth, 12);
            }
            if (ds.channelBlocked) {
                ds.arr = Math.min(ds.arr, 2.4);              // blocked retail channel caps ARR short of the milestone
                ds.growth = Math.min(ds.growth, 35);
            }
            if (ds.salesDelayRun) {
                ds.growth = Math.min(ds.growth, 25);         // the pipeline slipped a quarter; growth case weakened
            }
            if (ds.networkNeglectRun) {
                ds.network = Math.min(ds.network, 150);      // most of the €400–600K left unused
            }

            ds.arrHistory.push(ds.arr);
            ds.runwayHistory.push(ds.runway);
            ds.identityHistory.push(ds.identity);
            ds.networkHistory.push(ds.network);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist composite score + grade to the reporting/grading layer every period
            // (results_utils.php::express_resolveDomainScore -> performance.overallScore). Scoring UNCHANGED.
            const _score = this._composite(ds);
            ds.performance = { overallScore: _score, grade: this._gradeLetter(_score) };

            return {
                period: state.currentPeriod,
                arr: ds.arr,
                arrDelta: Math.round(arrDelta * 100) / 100,
                runway: ds.runway,
                identity: ds.identity,
                identityDelta: Math.round(identityDelta),
                network: ds.network,
                growth: ds.growth,
                pathChosen: ds.pathChosen,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: _score,
                score: _score
            };
        }

        _growthLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 45) return t(`growth_strong`);
            if (v >= 20) return t(`growth_mid`);
            if (v > 5) return t(`growth_slow`);
            return t(`growth_stalled`);
        }

        _fmtArr(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(2);
            return lang === `es` ? `€` + s.replace(`.`, `,`) + `M` : `€` + s + `M`;
        }

        _fmtRunway(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            const mo = window.mySimulation ? window.mySimulation.t(`unit_months`) : `mo`;
            return (lang === `es` ? s.replace(`.`, `,`) : s) + ` ` + mo;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`runwayDisplay`, `domainState.runway`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.racine-card-runway`);
                if (card) {
                    card.classList.toggle(`racine-runway-danger`, n < 6);
                    card.classList.toggle(`racine-runway-safe`, n >= 12);
                }
                return self._fmtRunway(n);
            });

            uiManager.bind(`arrDisplay`, `domainState.arr`, (v) => self._fmtArr(Number(v)));

            uiManager.bind(`identityDisplay`, `domainState.identity`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.racine-card-identity`);
                if (card) card.classList.toggle(`racine-identity-danger`, n < 50);
                return `${n}`;
            });

            uiManager.bind(`networkDisplay`, `domainState.network`, (v) => `€${Math.round(Number(v))}K`);

            uiManager.bind(`growthDisplay`, `domainState.growth`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.racine-growth-bar`);
                if (bar) {
                    bar.classList.toggle(`racine-growth-good`, n >= 45);
                    bar.classList.toggle(`racine-growth-warn`, n >= 20 && n < 45);
                }
                return self._growthLabel(n);
            });

            // Focus slider readout.
            const fo = document.getElementById(`focusInput`);
            const foReadout = document.getElementById(`focusReadout`);
            if (fo && foReadout) {
                foReadout.textContent = fo.value;
                fo.addEventListener(`input`, function() { foReadout.textContent = fo.value; });
            }

            // Attention slider readout.
            const at = document.getElementById(`attentionInput`);
            const atReadout = document.getElementById(`attentionReadout`);
            if (at && atReadout) {
                atReadout.textContent = at.value;
                at.addEventListener(`input`, function() { atReadout.textContent = at.value; });
            }
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, en) => (t ? t(k) : en);
            return {
                racineChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_arr`, `ARR (€M ×20, shared axis)`),
                                data: [],
                                borderColor: `#2f6e44`,
                                backgroundColor: `rgba(47,110,68,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2f6e44`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_identity`, `Identity alignment (0–100)`),
                                data: [],
                                borderColor: `#4f9d5f`,
                                backgroundColor: `rgba(79,157,95,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#4f9d5f`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_runway`, `Runway (months ×8)`),
                                data: [],
                                borderColor: `#b8542b`,
                                backgroundColor: `rgba(184,84,43,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b8542b`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#46594c`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7a8a7e` }, grid: { color: `rgba(36,48,41,0.06)` },
                                title: { display: true, text: L(`chart_axis_scale`, `0–100 (normalised)`), color: `#7a8a7e` }
                            },
                            x: {
                                ticks: { color: `#7a8a7e` }, grid: { color: `rgba(36,48,41,0.04)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#7a8a7e` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.arrHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Normalise onto a shared 0–100 axis: ARR ×20 (so €3M -> 60), runway ×8 (so 9mo -> 72).
            const arrScaled = ds.arrHistory.map((v) => Math.min(100, Math.round(v * 20)));
            const runwayScaled = ds.runwayHistory.map((v) => Math.min(100, Math.round(v * 8)));
            return {
                racineChart: {
                    labels: labels,
                    datasets: [
                        { data: arrScaled },
                        { data: ds.identityHistory.map((v) => Math.round(v)) },
                        { data: runwayScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            const arr = Math.round(ds.arr * 100) / 100;
            const runway = Math.round(ds.runway * 10) / 10;
            const identity = Math.round(ds.identity);
            const network = Math.round(ds.network);
            const arrScore = Math.min(100, (arr / this.MILESTONE_ARR) * 100);
            const runwayScore = Math.min(100, (runway / 12) * 100);
            const networkScore = Math.min(100, (network / this.NETWORK_MAX) * 100);
            return Math.round(arrScore * 0.30 + identity * 0.30 + runwayScore * 0.22 + networkScore * 0.18);
        }

        _verdictKey(ds, composite) {
            const arr = Math.round(ds.arr * 100) / 100;
            const runway = Math.round(ds.runway * 10) / 10;
            const identity = Math.round(ds.identity);
            const network = Math.round(ds.network);
            const growth = Math.round(ds.growth);
            const hitMilestone = arr >= this.MILESTONE_ARR;
            const identityIntact = identity >= 65;
            const solvent = runway >= 6;
            const leveraged = network >= this.NETWORK_FLOOR;
            const cleanRun = !ds.valuationTunnelRun && !ds.freeMoneyRun && !ds.bootstrapBlindRun && !ds.salesDelayRun && !ds.misdiagnosedRun && !ds.hyperGrowthRun;
            if (hitMilestone && identityIntact && solvent && leveraged && cleanRun && composite >= 75) return `verdict_sustainable`;
            if (ds.valuationTunnelRun) return `verdict_valuation`;
            if (ds.freeMoneyRun) return `verdict_freemoney`;
            if (ds.bootstrapBlindRun) return `verdict_purism`;
            if (ds.networkNeglectRun && !leveraged) return `verdict_network`;
            if (ds.salesDelayRun && growth < 25) return `verdict_conservative`;
            if (ds.hyperGrowthRun) return `verdict_velocity`;
            if (identityIntact && solvent && composite >= 55) return `verdict_slower`;
            if (composite >= 50) return `verdict_mixed`;
            return `verdict_burned`;
        }

        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 75) return `B`;
            if (c >= 62) return `C`;
            if (c >= 50) return `D`;
            if (c >= 35) return `E`;
            return `F`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const arr = Math.round(ds.arr * 100) / 100;
            const runway = Math.round(ds.runway * 10) / 10;
            const identity = Math.round(ds.identity);
            const network = Math.round(ds.network);
            const growth = Math.round(ds.growth);

            // Thresholds tied to the numbers reference card.
            const hitMilestone = arr >= this.MILESTONE_ARR;       // €3M ARR credible next raise
            const identityIntact = identity >= 65;                // the moat survived
            const solvent = runway >= 6;                          // raised from strength, not desperation
            const leveraged = network >= this.NETWORK_FLOOR;      // €400K+ network value unlocked

            // Composite (balanced — no single lever wins it).
            const composite = this._composite(ds);

            // Pattern detection — sticky flags define the run.
            let pattern = `mixed`;
            if (ds.valuationTunnelRun) pattern = `valuation_tunnel`;
            else if (ds.freeMoneyRun) pattern = `free_money`;
            else if (ds.bootstrapBlindRun) pattern = `bootstrap_blind`;
            else if (ds.networkNeglectRun && !leveraged) pattern = `network_neglect`;
            else if (ds.salesDelayRun) pattern = `over_conservative`;
            else if (ds.hyperGrowthRun) pattern = `unsustainable_rate`;
            else if (hitMilestone && identityIntact && solvent && leveraged) pattern = `sustainable`;

            // Verdict — GATED so the headline anti-patterns cannot reach the top.
            // hyperGrowthRun is included: chasing a velocity the resources can't carry is the
            // opposite of growing "on purpose", so it cannot reach the sustainable-rate top verdict.
            const cleanRun = !ds.valuationTunnelRun && !ds.freeMoneyRun && !ds.bootstrapBlindRun && !ds.salesDelayRun && !ds.misdiagnosedRun && !ds.hyperGrowthRun;
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const verdictKey = this._verdictKey(ds, composite);
            const performance = T(verdictKey);

            const insights = [];
            if (verdictKey === `verdict_sustainable`) insights.push(window.mySimulation.t(`insight_sustainable`));
            else if (ds.valuationTunnelRun) insights.push(window.mySimulation.t(`insight_valuation_tunnel`));
            else if (ds.freeMoneyRun) insights.push(window.mySimulation.t(`insight_free_money`));
            else if (ds.bootstrapBlindRun) insights.push(window.mySimulation.t(`insight_bootstrap_blind`));
            else if (ds.hyperGrowthRun) insights.push(window.mySimulation.t(`insight_unsustainable_rate`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.networkNeglectRun && !leveraged) insights.push(window.mySimulation.t(`insight_network_neglect`));
            if (ds.salesDelayRun) insights.push(window.mySimulation.t(`insight_sales_delay`));
            if (ds.channelBlocked) insights.push(window.mySimulation.t(`insight_channel_blocked`));
            if (!solvent) insights.push(window.mySimulation.t(`insight_runway_out`));
            if (identity < 50) insights.push(window.mySimulation.t(`insight_identity_lost`));
            if (!hitMilestone && identityIntact && solvent) insights.push(window.mySimulation.t(`insight_too_slow`));

            return {
                arr: arr,
                runway: runway,
                identity: identity,
                network: network,
                growth: growth,
                hitMilestone: hitMilestone,
                identityIntact: identityIntact,
                solvent: solvent,
                leveraged: leveraged,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                verdictKey: verdictKey,
                grade: this._gradeLetter(composite),
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const s = summary || {};
            const score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            const grade = s.grade || '';
            const verdict = s.performance || (s.verdictKey ? T(s.verdictKey) : '');
            const arr = this._fmtArr(Number(s.arr || 0));
            const identity = Math.round(Number(s.identity || 0));
            const runway = this._fmtRunway(Number(s.runway || 0));
            const network = '\u20AC' + Math.round(Number(s.network || 0)) + 'K';
            const growth = Math.round(Number(s.growth || 0)) + '%';
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map((t) => '<li>' + t + '</li>').join('');
            const onpurpose = s.verdictKey === 'verdict_sustainable';
            const badgeCls = onpurpose ? 'gop-cm-yes' : (score >= 62 ? 'gop-cm-mid' : 'gop-cm-no');
            const metric = (val, lab) => '<div class="gop-cm-metric"><span class="gop-cm-mv">' + val + '</span><span class="gop-cm-ml">' + lab + '</span></div>';
            const metrics = metric(arr, T('cm_m_arr'))
                + metric(identity, T('cm_m_identity'))
                + metric(runway, T('cm_m_runway'))
                + metric(network, T('cm_m_network'))
                + metric(growth, T('cm_m_growth'));
            return ''
                + '<div class="gop-completion">'
                +   '<div class="gop-cm-head">'
                +     '<div class="gop-cm-score">' + score + '<span class="gop-cm-score-max">/100</span></div>'
                +     '<div class="gop-cm-grade">' + verdict + ' <span class="gop-cm-badge ' + badgeCls + '">' + T('cm_grade') + ' ' + grade + '</span></div>'
                +   '</div>'
                +   '<div class="gop-cm-metrics">' + metrics + '</div>'
                +   '<div class="gop-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="gop-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.valuationTunnelRun) return window.mySimulation.t(`hint_valuation_tunnel`);
            if (ds.freeMoneyRun) return window.mySimulation.t(`hint_free_money`);
            if (ds.bootstrapBlindRun) return window.mySimulation.t(`hint_bootstrap_blind`);
            if (ds.runway < 6) return window.mySimulation.t(`hint_runway`);
            if (ds.networkNeglectRun && state.currentPeriod >= 2) return window.mySimulation.t(`hint_network`);
            if (ds.salesDelayRun) return window.mySimulation.t(`hint_sales_delay`);
            if (ds.identity >= 65 && ds.arr >= this.MILESTONE_ARR && ds.runway >= 6) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.arr`, label: `ARR`, i18nKey: `col_arr`, formatter: (v) => self._fmtArr(Number(v)) },
                { key: `results.runway`, label: `Runway`, i18nKey: `col_runway`, formatter: (v) => self._fmtRunway(Number(v)) },
                { key: `results.identity`, label: `Identity`, i18nKey: `col_identity`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.network`, label: `Network`, i18nKey: `col_network`, formatter: (v) => `€${Math.round(v)}K` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

